# Update admin_routes.py for manage_smtp_settings
old_admin = """            set_app_setting("default_sender", default_sender)
            set_app_setting("send_mode", send_mode)

            flash("发信配置已保存并立即生效", "success")"""
new_admin = """            set_app_setting("default_sender", default_sender)
            set_app_setting("send_mode", send_mode)
            
            auto_refresh_interval = (request.form.get("auto_refresh_interval") or "").strip()
            if auto_refresh_interval:
                set_app_setting("auto_refresh_interval", auto_refresh_interval)

            flash("邮件配置已保存并立即生效", "success")"""

admin_content = admin_content.replace(old_admin, new_admin)
with open("app/routes/admin_routes.py", "w", encoding="utf-8") as f:
    f.write(admin_content)


